function GroupConversationAvatar({ emptyIcon = 'people', members = [], photoUrl, variant = 'chatCircle' }) {
  const avatarMembers = uniqueById((members ?? []).filter(Boolean)).slice(0, 3);
  const rootStyle = variant === 'chatHeader'
    ? styles.groupAvatarRootChatHeader
    : variant === 'chatPicker'
      ? styles.groupAvatarRootPicker
      : styles.groupAvatarRootChatCircle;
  const photoStyle = variant === 'chatHeader'
    ? styles.groupAvatarPhotoChatHeader
    : variant === 'chatPicker'
      ? styles.groupAvatarPhotoPicker
      : styles.groupAvatarPhotoChatCircle;
  const tileLayouts = avatarMembers.length === 1
    ? [styles.groupAvatarTileSingle]
    : avatarMembers.length === 2
      ? [styles.groupAvatarTileLeft, styles.groupAvatarTileRight]
      : [styles.groupAvatarTileTop, styles.groupAvatarTileBottomLeft, styles.groupAvatarTileBottomRight];
  const fallbackColors = [STUDOS_THEME.blue, STUDOS_THEME.red, STUDOS_THEME.yellow];

  if (photoUrl) {
    return (
      <View style={rootStyle}>
        <Image source={{ uri: photoUrl }} style={photoStyle} />
      </View>
    );
  }

  if (!avatarMembers.length) {
    return (
      <View style={[rootStyle, styles.groupAvatarEmpty]}>
        <Ionicons
          name={emptyIcon}
          size={variant === 'chatCircle' ? 18 : 22}
          color={STUDOS_THEME.red}
        />
      </View>
    );
  }

  return (
    <View style={rootStyle}>
      {avatarMembers.map((member, index) => {
        const photo = member?.profilePhotoUrl;

        return (
          <View
            key={`${member?.id ?? member?.displayName ?? 'member'}-${index}`}
            style={[styles.groupAvatarTile, tileLayouts[index]]}
          >
            {photo ? (
              <Image source={{ uri: photo }} style={styles.groupAvatarTileImage} />
            ) : (
              <View
                style={[
                  styles.groupAvatarInitialsTile,
                  { backgroundColor: fallbackColors[index % fallbackColors.length] },
                ]}
              >
                <Text
                  adjustsFontSizeToFit
                  minimumFontScale={0.72}
                  numberOfLines={1}
                  style={[
                    styles.groupAvatarInitialsText,
                    index === 1 ? styles.groupAvatarInitialsTextLight : styles.groupAvatarInitialsTextDark,
                  ]}
                >
                  {initialsFor(member)}
                </Text>
              </View>
            )}
          </View>
        );
      })}
    </View>
  );
}

function useScaleAnim(scaleDown = 0.97) {
  const scale = useRef(new Animated.Value(1)).current;
  const spring = (v) => Animated.spring(scale, { toValue: v, useNativeDriver: true, tension: 220, friction: 18 }).start();
  return { scale, onPressIn: () => spring(scaleDown), onPressOut: () => spring(1) };
}

function ChatConversationRow({ conversation, isMemberOnline, lastMessagePreview, lastMessageTime, onLongPress, onPress, otherMember }) {
  const { scale, onPressIn, onPressOut } = useScaleAnim(0.97);
  const muted = isConversationMuted(conversation);
  const accessibilityParts = [
    conversation.title,
    muted ? 'Notifikationer slået fra' : null,
    conversation.unreadCount > 0 ? `${conversation.unreadCount} ulæste beskeder` : null,
    lastMessagePreview,
  ].filter(Boolean);

  return (
    <Animated.View style={{ transform: [{ scale }] }}>
      <Pressable
        accessibilityHint="Hold inde for chatindstillinger"
        accessibilityLabel={accessibilityParts.join('. ')}
        accessibilityRole="button"
        delayLongPress={280}
        onLongPress={onLongPress}
        onPress={onPress}
        onPressIn={onPressIn}
        onPressOut={onPressOut}
        style={styles.chatConversationRow}
      >
        {({ pressed }) => (
          <>
            <View pointerEvents="none" style={styles.chatConversationTail} />
            {conversation.unreadCount > 0 ? (
              <View style={styles.chatUnreadBadge}>
                <Text numberOfLines={1} style={styles.chatUnreadText}>{conversation.unreadCount}</Text>
              </View>
            ) : null}
            {conversation.type === 'direct' && otherMember ? (
              <View style={styles.chatConversationAvatarStatusWrap}>
                <Avatar profile={otherMember} variant="chatCircle" />
                {isMemberOnline ? <View style={styles.chatConversationOnlineDot} /> : null}
              </View>
            ) : (
              <GroupConversationAvatar
                members={conversation.participants?.map((participant) => participant.member)}
                photoUrl={conversation.groupPhotoUrl}
                variant="chatCircle"
              />
            )}
            <View style={styles.chatConversationCopy}>
              <View style={styles.chatConversationTitleRow}>
                <Text
                  numberOfLines={1}
                  style={[styles.chatConversationTitle, conversation.unreadCount > 0 ? styles.chatConversationTitleUnread : null]}
                >
                  {conversation.title}
                </Text>
                {muted ? (
                  <View style={styles.chatConversationMutedBadge}>
                    <Ionicons name="notifications-off" size={14} color={STUDOS_THEME.ink} />
                  </View>
                ) : null}
              </View>
              <View style={styles.chatConversationPreviewRow}>
                <Text numberOfLines={1} style={styles.chatConversationPreview}>{lastMessagePreview}</Text>
                {lastMessageTime ? (
                  <>
                    <View style={styles.chatConversationPreviewDot} />
                    <Text numberOfLines={1} style={styles.chatConversationPreviewTime}>{lastMessageTime}</Text>
                  </>
                ) : null}
              </View>
            </View>
            <View style={styles.chatConversationMeta}>
              <ChatConversationChevron unread={conversation.unreadCount > 0} />
            </View>
            {pressed ? (
              <View pointerEvents="none" style={styles.chatConversationHoldIndicator}>
                <Ionicons name="settings-sharp" size={15} color="#FFFFFF" />
              </View>
            ) : null}
          </>
        )}
      </Pressable>
    </Animated.View>
  );
}

const isConversationMuted = (conversation) => {
  const mutedUntil = conversation?.mutedUntil ? Date.parse(conversation.mutedUntil) : Number.NaN;

  return Number.isFinite(mutedUntil) && mutedUntil > Date.now();
};

