const selectSearchTextVariants = (value) => {
  const rawValue = String(value ?? '')
    .trim()
    .toLocaleLowerCase('da-DK')
    .replace(/\s+/g, ' ');

  if (!rawValue) {
    return [];
  }

  const stripMarks = (text) => text
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
  const normalizedValue = stripMarks(rawValue);
  const danishExpanded = stripMarks(rawValue
    .replace(/æ/g, 'ae')
    .replace(/ø/g, 'oe')
    .replace(/å/g, 'aa'));
  const danishSimple = stripMarks(rawValue
    .replace(/æ/g, 'a')
    .replace(/ø/g, 'o')
    .replace(/å/g, 'a'));

  return Array.from(new Set([normalizedValue, danishExpanded, danishSimple]));
};

const formatDate = (value) => {
  if (!value) {
    return '';
  }

  return new Intl.DateTimeFormat('da-DK', {
    day: '2-digit',
    month: 'short',
  }).format(new Date(`${value}T12:00:00`));
};

const formatDateTime = (value) => {
  if (!value) {
    return '';
  }

  const parsed = new Date(value);

  if (Number.isNaN(parsed.getTime())) {
    return '';
  }

  return new Intl.DateTimeFormat('da-DK', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  }).format(parsed);
};

