const formatProfileDate = (value) => {
  const rawValue = String(value ?? '').trim();

  if (!rawValue) {
    return 'Ikke angivet';
  }

  const dateFromYmd = rawValue.match(/^(\d{4})-(\d{2})-(\d{2})/);
  const date = dateFromYmd
    ? new Date(Number(dateFromYmd[1]), Number(dateFromYmd[2]) - 1, Number(dateFromYmd[3]))
    : new Date(rawValue);

  if (Number.isNaN(date.getTime())) {
    return 'Ikke angivet';
  }

  return new Intl.DateTimeFormat('da-DK', {
    day: '2-digit',
    month: 'long',
    year: 'numeric',
  }).format(date);
};

const isValidProfileBirthday = (value) => {
  const normalized = String(value ?? '').trim();

  if (!/^\d{4}-\d{2}-\d{2}$/.test(normalized)) {
    return false;
  }

  const [year, month, day] = normalized.split('-').map(Number);
  if (!Number.isFinite(year) || !Number.isFinite(month) || !Number.isFinite(day)) {
    return false;
  }

  const parsedDate = new Date(Date.UTC(year, month - 1, day));

  return !Number.isNaN(parsedDate.getTime())
    && parsedDate.getUTCFullYear() === year
    && parsedDate.getUTCMonth() + 1 === month
    && parsedDate.getUTCDate() === day;
};

const minimumAccountBirthdayValue = () => {
  const cutoff = new Date();

  cutoff.setFullYear(cutoff.getFullYear() - MINIMUM_ACCOUNT_AGE);

  return formatInputDate(cutoff);
};

const isProfileBirthdayOldEnough = (value) => {
  if (!isValidProfileBirthday(value)) {
    return false;
  }

  const [year, month, day] = String(value).split('-').map(Number);
  const birthday = new Date(year, month - 1, day, 12);
  const cutoff = new Date();

  cutoff.setFullYear(cutoff.getFullYear() - MINIMUM_ACCOUNT_AGE);
  cutoff.setHours(23, 59, 59, 999);

  return birthday.getTime() <= cutoff.getTime();
};

